#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

struct Tracer {
    std::string name;
    explicit Tracer(std::string n) : name(std::move(n)) {
        std::println("+{}", name);
    }
    ~Tracer() {
        std::println("-{}", name);
    }
};

void descend(const std::vector<std::string> &names, std::size_t i) {
    if (i == names.size()) {
        std::println("глубина {}", i);
        return;
    }
    const Tracer t(names[i]);
    descend(names, i + 1);
}

int main() {
    std::vector<std::string> names;
    std::string w;
    while (std::cin >> w) {
        names.push_back(w);
    }
    descend(names, 0);
    return 0;
}

