    std::string line;
    while (std::getline(std::cin, line)) {
        if (split(line).empty()) {
            std::println("пустая строка");
            continue;
        }
        const std::string &first = split(line).front();
        const std::size_t count = split(line).size();
        std::println("первое: {}, слов: {}", first, count);
    }
    return 0;
}

