#include <algorithm>
#include <iostream>
#include <print>
#include <string>
#include <vector>

void close_block(std::vector<std::vector<std::string>> &blocks) {
    const std::vector<std::string> &block = blocks.back();
    for (auto it = block.rbegin(); it != block.rend(); ++it) {
        std::println("-{}", *it);
    }
    blocks.pop_back();
}

int main() {
    std::vector<std::vector<std::string>> blocks(1);
    std::vector<std::string> statics;
    std::string command;
    while (std::cin >> command) {
        if (command == "{") {
            blocks.emplace_back();
        } else if (command == "}") {
            close_block(blocks);
        } else {
            std::string name;
            std::cin >> name;
            if (command == "obj") {
                std::println("+{}", name);
                blocks.back().push_back(name);
            } else if (command == "tmp") {
                std::println("+{}", name);
                std::println("-{}", name);
            } else if (!std::ranges::contains(statics, name)) {
                std::println("+{}", name);
                statics.push_back(name);
            }
        }
    }
    while (!blocks.empty()) {
        close_block(blocks);
    }
    for (auto it = statics.rbegin(); it != statics.rend(); ++it) {
        std::println("-{}", *it);
    }
    return 0;
}

